module trash_game (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [207:0] deck,\n    output reg done,\n    output reg winner\n);\n\n    // State definitions\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] DEAL = 4'd1;\n    localparam [3:0] TURN_START = 4'd2;\n    localparam [3:0] DRAW = 4'd3;\n    localparam [3:0] CHECK = 4'd4;\n    localparam [3:0] NUMBER_STRATEGY = 4'd5;\n    localparam [3:0] JACK_STRATEGY = 4'd6;\n    localparam [3:0] FILL_SLOT = 4'd7;\n    localparam [3:0] UNCOVER = 4'd8;\n    localparam [3:0] DISCARD = 4'd9;\n    localparam [3:0] DONE_STATE = 4'd10;\n    \n    // Card values\n    localparam [3:0] JACK = 4'd10;\n    \n    // Internal registers\n    reg [3:0] deck_memory [0:51];  // 52 cards\n    reg [5:0] deck_ptr;\n    reg [3:0] current_card;\n    reg player_turn;\n    reg [9:0] theta_filled;\n    reg [9:0] friend_filled;\n    reg [39:0] theta_faceup;\n    reg [39:0] friend_faceup;\n    reg [1:0] seen_count [0:12];\n    reg [3:0] fsm_state;\n    reg [3:0] temp_slot;\n    \n    // Combinational signals\n    reg [3:0] best_slot_theta;\n    reg [3:0] lowest_unfilled_friend;\n    reg all_filled_theta;\n    reg all_filled_friend;\n    integer i;\n\n    // Best slot comb logic\n    always @(*) begin\n        best_slot_theta = 4'd0;\n        reg [1:0] best_remaining = 2'd3;\n        for (i = 0; i < 10; i = i + 1) begin\n            if (!theta_filled[i] && (seen_count[i] < best_remaining)) begin\n                best_remaining = seen_count[i];\n                best_slot_theta = i[3:0];\n            end\n        end\n    end\n\n    // Lowest unfilled friend slot\n    always @(*) begin\n        lowest_unfilled_friend = 4'd0;\n        for (i = 0; i < 10; i = i + 1) begin\n            if (!friend_filled[i]) begin\n                lowest_unfilled_friend = i[3:0];\n                break;\n            end\n        end\n    end\n\n    // All filled check\n    always @(*) begin\n        all_filled_theta = (theta_filled == 10'b1111111111);\n        all_filled_friend = (friend_filled == 10'b1111111111);\n    end\n\n    // Main FSM\n    always @(posedge clk or negedge rst_n) begin\n        integer j;\n        if (!rst_n) begin\n            fsm_state <= IDLE;\n            done <= 1'b0;\n            winner <= 1'b0;\n            deck_ptr <= 6'd0;\n            current_card <= 4'd0;\n            player_turn <= 1'b0;\n            theta_filled <= 10'd0;\n            friend_filled <= 10'd0;\n            theta_faceup <= 40'd0;\n            friend_faceup <= 40'd0;\n            for (j = 0; j < 13; j = j + 1) seen_count[j] <= 2'd0;\n            temp_slot <= 4'd0;\n        end else begin\n            case (fsm_state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) fsm_state <= DEAL;\n                end\n                \n                DEAL: begin\n                    for (j = 0; j < 52; j = j + 1) begin\n                        deck_memory[j] <= deck[j*4 +: 4];\n                    end\n                    deck_ptr <= 6'd80;  // Start at 20th card\n                    player_turn <= 1'b0;\n                    theta_filled <= 10'd0;\n                    friend_filled <= 10'd0;\n                    theta_faceup <= 40'd0;\n                    friend_faceup <= 40'd0;\n                    for (j = 0; j < 13; j = j + 1) seen_count[j] <= 2'd0;\n                    fsm_state <= TURN_START;\n                end\n                \n                TURN_START: fsm_state <= DRAW;\n                \n                DRAW: begin\n                    current_card <= deck_memory[deck_ptr[5:0]];\n                    deck_ptr <= deck_ptr + 6'd1;\n                    fsm_state <= CHECK;\n                end\n                \n                CHECK: begin\n                    if (current_card < JACK) fsm_state <= NUMBER_STRATEGY;\n                    else if (current_card == JACK) fsm_state <= JACK_STRATEGY;\n                    else fsm_state <= DISCARD;\n                end\n                \n                NUMBER_STRATEGY: begin\n                    if ((player_turn && !friend_filled[current_card]) ||\n                        (!player_turn && !theta_filled[current_card])) begin\n                        temp_slot <= current_card;\n                        fsm_state <= FILL_SLOT;\n                    end else begin\n                        fsm_state <= DISCARD;\n                    end\n                end\n                \n                JACK_STRATEGY: begin\n                    temp_slot <= player_turn ? lowest_unfilled_friend : best_slot_theta;\n                    fsm_state <= FILL_SLOT;\n                end\n                \n                FILL_SLOT: begin\n                    if (!player_turn) begin\n                        theta_filled[temp_slot] <= 1'b1;\n                        theta_faceup[temp_slot*4 +: 4] <= current_card;\n                        if (current_card <= 4'd12) seen_count[current_card] <= seen_count[current_card] + 2'd1;\n                        if (all_filled_theta) begin\n                            winner <= 1'b1;\n                            done <= 1'b1;\n                            fsm_state <= DONE_STATE;\n                        end else begin\n                            fsm_state <= UNCOVER;\n                        end\n                    end else begin\n                        friend_filled[temp_slot] <= 1'b1;\n                        friend_faceup[temp_slot*4 +: 4] <= current_card;\n                        if (current_card <= 4'd12) seen_count[current_card] <= seen_count[current_card] + 2'd1;\n                        if (all_filled_friend) begin\n                            winner <= 1'b0;\n                            done <= 1'b1;\n                            fsm_state <= DONE_STATE;\n                        end else begin\n                            fsm_state <= UNCOVER;\n                        end\n                    end\n                end\n                \n                UNCOVER: begin\n                    current_card <= deck_memory[player_turn ? (6'd10 + temp_slot) : temp_slot];\n                    fsm_state <= CHECK;\n                end\n                \n                DISCARD: begin\n                    if (current_card <= 4'd12) seen_count[current_card] <= seen_count[current_card] + 2'd1;\n                    player_turn <= !player_turn;\n                    fsm_state <= TURN_START;\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    fsm_state <= DONE_STATE;\n                end\n                \n                default: fsm_state <= IDLE;\n            endcase\n        end\n    end\nendmodule